// spec: .qa/e2e/specs/reminders.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { readReminders } from '../_helpers/reminders';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Напоминания', () => {
  test('RM-01 «תזכורות מהירות» — у каждой строки заголовок + пояснение и иконка справа, ближайшая молитва с окном, «ניהול תזכורות» #6a86f7fa #3cc72778 @prod-safe @mobile', async ({ page }) => {
    // 1. Открыть `/home` → блок «תזכורות מהירות».
    await page.goto('/home');
    const title = page.getByText('תזכורות מהירות', { exact: true });
    await expect(title).toBeVisible({ timeout: 20_000 });
    const block = title.locator('xpath=../..');

    // «ניהול תזכורות» (a11y «ניהול התזכורות במסך הפרופיל»)
    const manage = block.getByRole('button', { name: 'ניהול התזכורות במסך הפרופיל' });
    await expect(manage).toBeVisible();
    await expect(manage).toContainText('ניהול תזכורות');

    // Каждая строка — 2 строки текста (заголовок + пояснение)
    const rows = block.locator('xpath=./div[position()>1]');
    await expect(rows.first()).toBeVisible();
    const count = await rows.count();
    expect(count).toBeGreaterThanOrEqual(1);
    const texts: string[] = [];
    for (let i = 0; i < count; i++) {
      const lines = (await rows.nth(i).innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
      expect(lines, `строка ${i + 1}: заголовок + пояснение`).toHaveLength(2);
      texts.push(...lines);
    }

    // Строка ближайшей молитвы (первая) содержит время окончания окна HH:MM
    const firstLines = (await rows.first().innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
    expect(firstLines[1]).toMatch(/\d{2}:\d{2}/);

    // У каждой строки кружок с иконкой — справа от текста (RTL), как в Figma 608:1389 (#3cc72778, ответ 30.09 f5fb9b9 и фикс 4.10)
    const geo = await readReminders(page);
    for (const r of geo) expect(r.iconRight, `«${r.title}»: кружок с иконкой справа`).toBe(true);

    // Нет пустого/сломанного блока; нет латиницы и «undefined»
    const whole = await block.innerText();
    expect(whole).not.toMatch(/undefined|null|NaN/);
    expect(whole).not.toMatch(/[A-Za-z]/);
    expect(texts.every((t) => /[א-ת]/.test(t))).toBe(true);
  });
});
